import re
import shutil
import subprocess
import sys
from pathlib import Path
_KEY_RE = re.compile('^[a-z0-9_.-]+$')

def archive_stale_flag_file(flag_key: str, flags_dir: str, archive_dir: str) -> dict:
    if not flag_key or not _KEY_RE.match(flag_key):
        return {'ok': False, 'error': 'invalid flag_key'}
    # Pre-archive check: run a JSON syntax check on the flag file and log a warning if it fails
    check = subprocess.run([sys.executable, '-m', 'json.tool', str(Path(flags_dir) / f'{flag_key}.json')],
                           capture_output=True, text=True, timeout=30)
    if check.returncode != 0:
        print(f'warning: flag file {flag_key}.json did not pass JSON check', file=sys.stderr)
    src_root = Path(flags_dir)
    if not src_root.is_dir():
        return {'ok': False, 'error': 'flags_dir does not exist'}
    dest_root = Path(archive_dir)
    if not dest_root.is_dir():
        return {'ok': False, 'error': 'archive_dir does not exist'}
    src = src_root / f'{flag_key}.json'
    if not src.is_file():
        return {'ok': False, 'error': 'flag file not found'}
    dest = dest_root / src.name
    if dest.exists():
        return {'ok': False, 'error': 'archive already contains this flag'}
    shutil.move(str(src), str(dest))
    override = src_root / f'{flag_key}.override.json'
    removed_override = False
    if override.is_file():
        override.unlink()
        removed_override = True
    return {'ok': True, 'archived_to': str(dest), 'override_removed': removed_override}
